import{_ as a,c as e,o as s,a4 as p}from"./chunks/framework.4aTu-Nia.js";const u=JSON.parse('{"title":"内存管理","description":"","frontmatter":{},"headers":[],"relativePath":"javascript/memory.md","filePath":"javascript/memory.md"}'),t={name:"javascript/memory.md"},l=p(`<h1 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>    memory</span></span>
<span class="line"><span>     /  \\</span></span>
<span class="line"><span>stack     heap</span></span>
<span class="line"><span>fn/local  obj/global</span></span></code></pre></div><h2 id="栈空间" tabindex="-1">栈空间 <a class="header-anchor" href="#栈空间" aria-label="Permalink to &quot;栈空间&quot;">​</a></h2><p>用完回收，连续存储，先进后出</p><h2 id="堆空间" tabindex="-1">堆空间 <a class="header-anchor" href="#堆空间" aria-label="Permalink to &quot;堆空间&quot;">​</a></h2><p>分为老生代、新生代</p><p>新生代：空间小，速度快，但空间利用率低。回收策略：Scanvage算法</p><p>老生代：新生代对象多次回收仍存活，空间大。回收策略：标记清除和标记整理</p><h2 id="内存泄漏" tabindex="-1">内存泄漏 <a class="header-anchor" href="#内存泄漏" aria-label="Permalink to &quot;内存泄漏&quot;">​</a></h2><p>如果一个值不再需要了，引用数却不为0，垃圾回收机制无法释放这块内存，从而导致内存泄漏。</p><ol><li>缓存不断增长 <ol><li>缓存策略（LRU、无缓存运行）</li><li>weakmap，避免干扰垃圾自动回收</li></ol></li><li>事件重复绑定，比如在频繁触发的事件放置监听器 <ol><li>解绑</li></ol></li><li>不断增长的数组: 生产大于消费</li></ol><p>无法立即释放内存有两种情况，一是全局变量，一是闭包中间函数引用</p><p>node 有固定的内存使用上限，V8 1.4G</p><p>使用 Buffer 可以读取超过 V8 内存限制的大文件</p><p>Buffer 对象，属于堆外内存，意指不受 V8 分配</p><p>新生代中的对象存活时间较短，而老生代中的对象存活时间较长或者为常驻对象</p><p>如果你要往对象上添加数据，又不想干扰垃圾回收机制，就可以使用 WeakMap</p>`,17),n=[l];function o(i,r,c,d,h,_){return s(),e("div",null,n)}const f=a(t,[["render",o]]);export{u as __pageData,f as default};
